/*
 * The electrical picture is sampled at 160 x 144 Game Boy cell resolution.
 * The evolving director state uses the nominal WS2 physical-response drift
 * field generated by JohnnySun/retro-display-lab; no whole-frame blur.
 */
import {REFRESH_HZ,TARGET_Q,DRIFT_Q,OPTICAL_LUT,ANCHOR_Q,CORRECTION} from './physics-data.js';
export const LCD_W=160,LCD_H=144,PIXELS=LCD_W*LCD_H;
const clamp=(x,lo=0,hi=1)=>Math.min(hi,Math.max(lo,x));
const lerp=(a,b,t)=>a+(b-a)*t;
const sample=(table,q)=>{
 const p=clamp(q)*64,i=Math.min(63,Math.floor(p));
 return lerp(table[i],table[i+1],p-i);
};
function visibleState(q){
 let s=sample(OPTICAL_LUT,q),c;
 if(q<=ANCHOR_Q[0]) c=CORRECTION[0]*q/Math.max(ANCHOR_Q[0],1e-6);
 else if(q<=ANCHOR_Q[3]){
  const n=q<=ANCHOR_Q[1]?0:q<=ANCHOR_Q[2]?1:2;
  c=lerp(CORRECTION[n],CORRECTION[n+1],(q-ANCHOR_Q[n])/(ANCHOR_Q[n+1]-ANCHOR_Q[n]));
 }else c=CORRECTION[3]*(1-q)/Math.max(1-ANCHOR_Q[3],1e-6);
 return clamp(s+c,.25,1);
}
export class PanelPhysics {
 constructor(){
  this.drive=new Uint8Array(PIXELS);
  this.q=new Float32Array(PIXELS);
  this.ions=new Float32Array(PIXELS);
  this.optical=new Uint8Array(PIXELS);
  this.charged=false;this.elapsed=0;
  this.reset();
 }
 reset(){
  for(let k=0;k<PIXELS;k++){
   this.q[k]=TARGET_Q[this.drive[k]];
   this.ions[k]=this.drive[k]/3;
   this.optical[k]=Math.round(visibleState(this.q[k])*255);
  }
  this.elapsed=0;
 }
 setPicture(picture){
  if(picture.length!==PIXELS)throw Error('Invalid logical LCD picture');
  this.drive.set(picture);
 }
 step(seconds,{temperature=20,retain=true}={}){
  let total=Math.min(.1,Math.max(0,seconds))*REFRESH_HZ;
  const tK=temperature+273.15;
  const thermal=Math.exp(3800*(1/293.15-1/tK));
  // Split longer display intervals to keep the generated drift field stable.
  const count=Math.max(1,Math.ceil(total/.45));
  const fraction=total/count;
  for(let sub=0;sub<count;sub++){
   for(let k=0;k<PIXELS;k++){
    const drive=this.drive[k],p=this.q[k]*64;
    const j=Math.min(63,Math.max(0,Math.floor(p)));
    const low=DRIFT_Q[drive*65+j],high=DRIFT_Q[drive*65+j+1];
    const velocity=lerp(low,high,clamp(p-j));
    this.q[k]=clamp(this.q[k]+velocity*fraction*thermal);
    if(retain){
     const aim=drive/3,old=this.ions[k];
     const rate=aim>old?.000126777389:.000007115625;
     this.ions[k]=old+(aim-old)*(1-Math.pow(1-rate,fraction));
    }
   }
  }
  for(let k=0;k<PIXELS;k++){
   const drive=this.drive[k],bias=retain?
     Math.max(this.ions[k]-drive/3,0)*Math.max(7.390426*.05-.186987,0)*.082:0;
   this.optical[k]=Math.round(clamp(visibleState(this.q[k])+bias,.25,1)*255);
  }
  this.elapsed+=seconds;
  return this.optical;
 }
 getImage(){return this.optical;}
}
const scratch=document.createElement('canvas');
scratch.width=LCD_W;scratch.height=LCD_H;
const ctx=scratch.getContext('2d',{willReadFrequently:true});
const P=['#ffffff','#aaaaaa','#555555','#000000'];
function piece(x,y,cells,cell=7,border=true){
 ctx.fillStyle=P[3];
 for(const [px,py] of cells){
  const bx=x+px*cell,by=y+py*cell;
  ctx.fillRect(bx,by,cell,cell);
  if(border&&cell>4){ctx.fillStyle=P[2];ctx.fillRect(bx+1,by+1,cell-2,cell-2);ctx.fillStyle=P[3];}
 }
}
export function makePicture(scene='title',step=0){
 ctx.fillStyle=P[0];ctx.fillRect(0,0,LCD_W,LCD_H);
 ctx.textAlign='center';ctx.textBaseline='middle';
 if(scene==='title'){
  ctx.fillStyle=P[3];ctx.font='bold 27px monospace';ctx.fillText('TETRIS',80,39);
  ctx.fillStyle=P[2];ctx.font='bold 10px monospace';ctx.fillText('SYSTEM',80,61);
  ctx.fillStyle=P[3];ctx.fillRect(31,86,98,27);
  ctx.fillStyle=P[0];ctx.fillRect(34,89,92,21);
  ctx.fillStyle=P[3];ctx.font='bold 14px monospace';ctx.fillText('START',80,100);
  ctx.font='bold 7px monospace';ctx.fillText('NOMAD  /  LCD LAB',80,131);
  piece(12,14,[[0,0],[1,0],[1,1],[2,1]],6);
  piece(130,15,[[1,0],[0,1],[1,1],[2,1]],6);
 }else if(scene==='motion'){
  ctx.fillStyle=P[3];ctx.font='bold 8px monospace';ctx.fillText('LCD RESPONSE STUDY',80,12);
  ctx.fillStyle=P[2];ctx.fillRect(43,21,74,109);
  ctx.fillStyle=P[0];ctx.fillRect(45,23,70,105);
  for(let y=32;y<123;y+=10){ctx.fillStyle=P[1];ctx.fillRect(46,y,68,1);}
  ctx.fillStyle=P[3];ctx.fillRect(46,120,68,7);
  const cell=9,yy=24+Math.floor(step%9)*10;
  piece(61,yy,[[0,0],[1,0],[1,1],[2,1]],cell);
  ctx.fillStyle=P[3];ctx.font='bold 7px monospace';ctx.fillText('SHADOW / TRANSMISSION',80,138);
 }else if(scene==='shades'){
  ctx.fillStyle=P[3];ctx.font='bold 9px monospace';ctx.fillText('FOUR DRIVE LEVELS',80,15);
  for(let n=0;n<4;n++){
   ctx.fillStyle=P[n];ctx.fillRect(18,29+n*25,124,21);
   ctx.fillStyle=n>1?P[0]:P[3];
   ctx.font='bold 10px monospace';ctx.fillText('SHADE '+n,80,39+n*25);
  }
 }else if(scene==='grid'){
  ctx.fillStyle=P[3];ctx.font='bold 10px monospace';ctx.fillText('CELL GEOMETRY',80,14);
  for(let y=27;y<129;y+=13)for(let x=13;x<152;x+=13){
   const shade=(Math.floor(x/13)+Math.floor(y/13))%4;
   ctx.fillStyle=P[shade];ctx.fillRect(x,y,11,11);
  }
 }
 const data=ctx.getImageData(0,0,LCD_W,LCD_H).data;
 const logical=new Uint8Array(PIXELS);
 for(let i=0;i<PIXELS;i++)logical[i]=Math.round((255-data[i*4])/85);
 return logical;
}
